import 'mocha';
const supertest = require('supertest');
import * as http from 'http';
import {strict as assert} from 'assert';
import * as rp from 'request-promise';
import {CloudEvent} from '../src/interface';
import {CloudEvents} from '../src';

describe('CloudEvents', () => {
  describe('CE Object', () => {
    /**
     * Creates a structured CloudEvent
     * @see https://github.com/cloudevents/spec/blob/master/spec.md#example
     */
    it('should create a structured event like the sample in the spec.', () => {
      const ce: CloudEvent = {
        specversion : "1.0",
        type : "com.github.pull.create",
        source : "https://github.com/cloudevents/spec/pull",
        subject : "123",
        id : "A234-1234-1234",
        time : "2018-04-05T17:31:00Z",
        comexampleextension1 : "value",
        comexampleothervalue : 5,
        datacontenttype : "text/xml",
        data : "<much wow=\"xml\"/>"
      };

      // Trivial test, but should be type-safe.
      assert.equal(Object.keys(ce).length, 10);
    });

    /**
     * This tests a real-life CloudEvent object in the CloudEvent client.
     */
    it('should create AWS S3 events', () => {
      const s3: CloudEvent = {
        // CloudEvents metadata data goes here
        type: "aws.s3.object.created",
        id: "C1234-1234-1234",
        time: "2018-05-08T14:48:09.769Z",
        specversion: "1.0",
        source: "/cloudevents-bucket",

        extensions: {},
        contentType: "application/json",
        
        // Your custom event data goes here
        data: {
          "s3SchemaVersion": "1.0",
          "configurationId": "cd267a38-30df-412e-9e3d-d0f1ca6e2410",
          "bucket": {
            "name": "cloudevents",
            "ownerIdentity": {},
            "arn": "arn:aws:s3:::cloudevents"
          },
          "object": {
            "key": "cross-eyed-cat.jpg",
            "size": 444684,
            "eTag": "38b01ff161231d7ca0a0eb3f7a88ff815",
            "sequencer": "005AEOAJ31A9A3D61490"
          }
        }
      };
      const ce = CloudEvents.newEvent(s3);

      // Silly assertion.
      assert.equal(Object.keys(ce).length > 5, true);
    });
  });

  describe('CE client', () => {
    /**
     * E2E tests creating a new client and sending a CloudEvent to a local server.
     */
    it('should be able to create a new client and sent an event', (done) => {
      // Create a client
      const transport = CloudEvents.newHTTPTransport({
        target: 'http://localhost:3000/',
        encoding: CloudEvents.HTTPStructuredV1,
      });
      const client = CloudEvents.newClient({ transport })
      
      // Create an event
      const event = CloudEvents.newEvent({
        id: 'ABC-123',
        type: 'com.cloudevents.readme.sent',
        source: 'http://my-website.com/',
        specversion: '1.0',
        data: { foo: 'bar'},
      });

      // Create a server
      const server = require('./server');

      // TODO: Assert that client.send() did POST
      supertest(server)
        .post('/').send() // POST
        // .expect((done) => {
        //   // Send the event
        //   // client.send(event).then((res) => {
        //   //   assert.deepEqual(res.data, { text: 'ok cool'});
        //   // });
        //   done();
        // });
      client.send(event);
      done();
    });
  });
});